{
    "name_generation_rules": {
        "description": "自动生成名字的规则",
        "user_name_generation": {
            "description": "自动生成 {{user}} 的名字(男性)",
            "rule": "依据算法，生成独一无二且适配游戏整体背景的名字。名字形式丰富多样，比如在奇幻游戏里，可能会融入独特的魔法元素相关字词；科幻游戏中，则可能包含具有科技感的词汇等"
        },
        "female_npc_name_generation": {
            "world_location_rules": {
                "international": {
                    "description": "当游戏场景设定在国外时生成女性 NPC 名字的规则",
                    "example_names": ["露易丝", "安娜"],
                    "rule": "广泛参考欧美、日韩等不同地域的女性名字特征。生成欧美名字时，可从经典英文名库中挑选或巧妙组合，像常见的以元音起始的优雅名字；生成日韩名字时，严格遵循其各自的命名习惯，仔细考量姓氏与名字的搭配。日本名字着重汉字的含义与美感，韩国名字则将传统姓氏与富有时代气息的名字相结合"
                },
                "domestic": {
                    "description": "当游戏场景设定在中国时生成女性 NPC 名字的规则",
                    "example_names": ["李婉怡", "陈嘉欣"],
                    "rule": "优先从《百家姓》等常见姓氏库中选取高频姓氏。名字部分侧重选取寓意美好的汉字，这些汉字可代表品德、容貌、志向等积极层面，同时兼顾音韵和谐，规避生僻字与拗口的组合。并且要充分考虑不同时代和地域的取名喜好，古代风格名字多借鉴诗词典故，现代风格名字更显时尚亲和"
                }
            }
        }
    }
}

